13 — Evaluate configured contrasts of contrasts
for label, left_a, left_b, right_a, right_b in contrast_of_contrasts:
    parts = [
        cells[key]
        for key in [tuple(left_a), tuple(left_b), tuple(right_a), tuple(right_b)]
    ]
    subjects = sorted(set.intersection(*(set(part) for part in parts)))
    differences = np.array(
        [(parts[0][s] - parts[1][s]) - (parts[2][s] - parts[3][s]) for s in subjects]
    )
    print(
        label,
        test_cat_recall_rate_pair(differences, np.zeros_like(differences)),
        sep="\n",
    )
    if len(differences) &gt; 1:
        interval = stats.t.interval(
            confidence_level,
            len(differences) - 1,
            loc=differences.mean(),
            scale=stats.sem(differences),
        )
        print(
            f"{confidence_level:.0%} interval for the difference of differences:",
            interval,
        )

